-- Accept only captured old/new rows. Reapply safely after a known partial write.
-- Check all scoped rows before changing anything, including under mysql --force.
SET NAMES utf8;
CREATE TEMPORARY TABLE `renataki_guard` (`ok` TINYINT PRIMARY KEY) ENGINE=MEMORY;
INSERT INTO `renataki_guard` VALUES (1);
LOCK TABLES `creature_template` READ, `creature_ai_scripts` READ, `creature_immunities` READ, `creature_loot_template` READ, `creature_spell_list_entry` READ, `creature_spell_list` READ, `creature_spell_targeting` READ, `spell_scripts` WRITE, `spell_template` READ, `spell_script_target` READ, `dbscripts_on_spell` READ;
